	private final List<String> touchedProperties = new ArrayList<>();
	private final Map<String, String> previousProperties = new java.util.HashMap<>();

	@AfterEach
	void restoreProperties() {
		for (String name : touchedProperties) {
			String previous = previousProperties.get(name);
			if (previous == null) {
				System.clearProperty(name);
			} else {
				System.setProperty(name, previous);
			}
		}
	}

	// ---------------------------------------------------------------- B2: lookup (tests 1, 2)

	@Test
	void aLearnedOnlyDriftWithAnUnchangedLogServesAReplayOnlyVariantAndRestampsIt() {
		try (Harness harness = new Harness()) {
			LmdbPipelinePlanCache.Context built = learned(17L, 3L);
			LmdbPipelinePlanCache.Context drifted = learned(17L, 30L);
			harness.publish(built, false);
			long familyVersion = harness.familyVersion();

			StubValidator validator = new StubValidator(LmdbPlanningReadLog.Verdict.IDENTICAL);
			LmdbPipelinePlanCache.Result served = harness.lookup(drifted, false, validator);

			assertAll(
					() -> assertTrue(served.cacheHit(), "an unchanged log revalidates a replay-only variant"),
					() -> assertEquals(1, harness.computations.get(), "nothing is re-planned"),
					() -> assertEquals("USE", served.plan()
							.getStringMetricPlanned(
									"optimizer.planCacheLookupOutcome")),
					() -> assertEquals(LmdbPlanCacheRevalidation.REVALIDATED,
							served.plan().getStringMetricPlanned("optimizer.planCacheRefreshReason")),
					() -> assertEquals(1, validator.calls.get()),
					() -> assertEquals(drifted.revision(), validator.expected.get(),
							"the replay's captures must equal the request's revision"),
					() -> assertEquals(familyVersion, harness.familyVersion(), "the re-stamp keeps the version number"),
					() -> assertEquals(LmdbPipelinePlanCache.evidence(drifted.revision().planningRevisions()),
							harness.variant().evidenceSnapshot(), "the variant now vouches for the request's evidence"),
					() -> assertEquals(1L, harness.revalidation().servedIdentical()),
					() -> assertEquals(1L, harness.revalidation().restamps()));
		}
	}

