	@Test
	void theConfiguredToleranceReachesTheReplayAndBitExactModeRefusesAMoveWithinIt(@TempDir Path directory)
			throws Exception {
		setProperty(LmdbPlanningReadLog.TOLERANCE_PROPERTY, "0");
		try (Harness replayOnly = new Harness(); Harness ranked = new Harness()) {
			LmdbOperatorFeedbackStats stats = feedback(directory);
			LogicalLearningKey key = logical("bit-exact");
			teach(stats, key, 40, 7L);
			replayOnly.publish(learned(17L, 3L), false, () -> logicalRead(stats, key));
			ranked.publish(learned(17L, 3L), true, () -> logicalRead(stats, key));
			teach(stats, key, 1, 7L);
			OwnerValidator validator = new OwnerValidator();

			LmdbPipelinePlanCache.Result replay = replayOnly.lookup(learned(17L, 30L), false, validator);
			LmdbPipelinePlanCache.Result rankedServe = ranked.lookup(learned(17L, 30L), true, validator);

			assertAll(
					() -> assertEquals(0.0d, validator.tolerances.get(0), 0.0d),
					() -> assertFalse(replay.cacheHit(), "bit-exact mode refuses a value that moved at all"),
					() -> assertEquals("USE_AND_REFRESH",
							rankedServe.plan().getStringMetricPlanned("optimizer.planCacheLookupOutcome")),
					() -> assertEquals(1L, replayOnly.revalidation().changed()),
					() -> assertEquals(1L, ranked.revalidation().changed()));
		}
	}

	@Test
	void cumulativeDriftAcrossRestampsIsMeasuredAgainstTheRecordedValueAndEndsAsChanged(@TempDir Path directory)
			throws Exception {
		try (Harness harness = new Harness()) {
			LmdbOperatorFeedbackStats stats = feedback(directory);
			LogicalLearningKey key = logical("drift");
			teach(stats, key, 40, 7L);
			harness.publish(learned(17L, 3L), false, () -> logicalRead(stats, key));
			LmdbPlanningReadLog.Log recorded = harness.variant().readLogBasis().log();
			assertTrue(recorded.readCount() > 0, "COVERAGE_PREREQUISITE: the planning's model read is in its log");

			OwnerValidator validator = new OwnerValidator();
			int servedWithin = 0;
			boolean replanned = false;
			double rows = 7.0d;
			for (int step = 1; step <= 400 && !replanned; step++) {
				rows *= 1.05d;
				teach(stats, key, 1, Math.round(rows));
				LmdbPipelinePlanCache.Result result = harness.lookup(learned(17L, 3L + step), false, validator);
				if (result.cacheHit()) {
					servedWithin++;
					assertSame(recorded, harness.variant().readLogBasis().log(),
							"a re-stamp keeps the recorded log, so drift accumulates against it");
				} else {
					replanned = true;
				}
			}
			int served = servedWithin;
			boolean ended = replanned;
			assertAll(
					() -> assertTrue(served > 0, "COVERAGE_PREREQUISITE: early steps are served within the tolerance"),
					() -> assertTrue(ended, "accumulated drift ends as a change"),
					() -> assertTrue(harness.revalidation().changed() >= 1L));
		}
	}

