	@Test
	void aPlanningStartIsMarkedOnlyAtDepthOneWithNothingRecordedBefore(@TempDir Path directory) throws Exception {
		LmdbOperatorFeedbackStats stats = feedback(directory);
		LogicalLearningKey key = logical("planning-start");
		LmdbPlanningReadLog.Mark outermost;
		LmdbPlanningReadLog.Mark afterARead;
		LmdbPlanningReadLog.Mark nested;
		LmdbPlanningReadLog.beginPlanning();
		try {
			outermost = LmdbPlanningReadLog.markAtPlanningStart();
			logicalRead(stats, key);
			afterARead = LmdbPlanningReadLog.markAtPlanningStart();
			LmdbPlanningReadLog.beginPlanning();
			try {
				nested = LmdbPlanningReadLog.markAtPlanningStart();
			} finally {
				LmdbPlanningReadLog.endPlanning();
			}
		} finally {
			LmdbPlanningReadLog.endPlanning();
		}
		LmdbPlanningReadLog.Mark afterAnIncompleteEvent;
		LmdbPlanningReadLog.beginPlanning();
		try {
			LmdbPlanningReadLog.markIncomplete("before-the-mark");
			afterAnIncompleteEvent = LmdbPlanningReadLog.markAtPlanningStart();
		} finally {
			LmdbPlanningReadLog.endPlanning();
		}
		// A lifecycle read made without enforcement: in a compact log the keyless guard (A2 rule 3').
		LmdbPlanningReadLog.Mark afterALifecycleRead;
		LmdbPlanningReadLog.beginPlanning();
		try {
			stats.planLifecycleDecision(logical("planning-start-lifecycle"), PHYSICAL, APPLICABILITY,
					new PlanLifecycleStore.ObjectiveEnvelope(50.0d, 60.0d, 70.0d));
			afterALifecycleRead = LmdbPlanningReadLog.markAtPlanningStart();
		} finally {
			LmdbPlanningReadLog.endPlanning();
		}
		assertAll(() -> assertNotNull(outermost, "an outermost planning with nothing recorded yet is marked"),
				() -> assertNull(afterARead, "a planning that already recorded a read is not marked"),
				() -> assertNull(nested, "a nested planning is not marked"),
				() -> assertNull(afterAnIncompleteEvent, "nor one already made incomplete"),
				() -> assertNull(afterALifecycleRead, "nor one that already holds a lifecycle read or guard"),
				() -> assertNull(LmdbPlanningReadLog.markAtPlanningStart(), "no planning scope, no mark"));
	}

