	// ---------------------------------------------------------------- B3: publication rescue (test 4)

	@Test
	void aPlanningWhoseRevisionMovedOnlyInLearnedStateIsPublishedUnderItsEndCaptureWhenItsLogReplays() {
		try (Harness harness = new Harness()) {
			LmdbPipelinePlanCache.Context start = learned(17L, 3L);
			LmdbPipelinePlanCache.Context end = learned(17L, 4L);
			StubValidator validator = new StubValidator(LmdbPlanningReadLog.Verdict.IDENTICAL);
			AtomicReference<LmdbPipelinePlanCache.Revision> current = new AtomicReference<>(start.revision());

			LmdbPipelinePlanCache.Result planned = harness.cache.getOrComputePlan(query("_anon_1"), start,
					current::get, () -> harness.decision(false, query("_anon_1"),
							() -> current.set(end.revision())),
					() -> Long.MIN_VALUE, validator);
			int replaysAtPublication = validator.calls.get();
			LmdbPipelinePlanCache.Result next = harness.lookup(end, false, validator);

			assertAll(
					() -> assertFalse(planned.cacheHit()),
					() -> assertEquals(1, replaysAtPublication, "the planning's own log is replayed once"),
					() -> assertEquals(0.0d, validator.tolerance.get(), 0.0d, "at tolerance 0"),
					() -> assertEquals(end.revision(), validator.expected.get(), "against the end capture"),
					() -> assertTrue(next.cacheHit(), "published under the end capture"),
					() -> assertEquals("replay-only-identical-request",
							next.plan().getStringMetricPlanned("optimizer.planCacheRefreshReason"),
							"the next lookup at the end capture is an ordinary exact hit"),
					() -> assertEquals(1, validator.calls.get(), "without a replay"),
					() -> assertEquals(1L, harness.revalidation().publicationsRescued()));
		}
	}

	@ParameterizedTest
	@ValueSource(strings = { "changed", "switch-off", "data-moved", "frontier-published" })
	void aPlanningWhoseRevisionMovedOtherwiseIsRefusedAsToday(String why) {
		if ("switch-off".equals(why)) {
			setProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY, "false");
		}
		try (Harness harness = new Harness()) {
			LmdbPipelinePlanCache.Context start = learned(17L, 3L);
			// F10: a planning spanning a Frontier publication (and a learned move) is refused although its log replays
			// identical: B3 rescues only differences in learned state.
			LmdbPipelinePlanCache.Context end = switch (why) {
			case "data-moved" -> learned(18L, 2L, 3L, 7L, 0L, true);
			case "frontier-published" -> learned(17L, 20L, 4L, 7L, 0L, true);
			default -> learned(17L, 4L);
			};
			StubValidator validator = new StubValidator("changed".equals(why) ? LmdbPlanningReadLog.Verdict.CHANGED
					: LmdbPlanningReadLog.Verdict.IDENTICAL, LmdbPlanningReadLog.SAMPLE);
			AtomicReference<LmdbPipelinePlanCache.Revision> current = new AtomicReference<>(start.revision());

			harness.cache.getOrComputePlan(query("_anon_1"), start, current::get,
					() -> harness.decision(false, query("_anon_1"), () -> current.set(end.revision())),
					() -> Long.MIN_VALUE, validator);

			assertAll(() -> assertEquals(0, harness.cache.entryCount(), "the moved planning is refused"),
					() -> assertEquals(0L, harness.revalidation().publicationsRescued()));
		}
	}

