	@Test
	void aRestampKeepsTheVersionNumberAndTheExecutionTokensAndTheNextLookupIsAnExactHit() {
		try (Harness harness = new Harness()) {
			harness.publish(learned(17L, 3L), true);
			LmdbPipelinePlanCache.Result before = harness.lookup(learned(17L, 3L), true, null);
			LmdbPlanDecisionCache.PlanExecutionToken token = token(before.plan());
			LmdbPipelinePlanCache.Context drifted = learned(17L, 30L);
			StubValidator validator = new StubValidator(LmdbPlanningReadLog.Verdict.IDENTICAL);

			LmdbPipelinePlanCache.Result revalidated = harness.lookup(drifted, true, validator);
			harness.cache.observeExecution(new LmdbPlanDecisionCache.ExecutionObservation(token.familyKey(),
					token.variantId(), token.planVersion(), true, false, 0.5d, 0L, false, false));
			LmdbPipelinePlanCache.Result exact = harness.lookup(drifted, true, validator);

			assertAll(
					() -> assertEquals(token.familyVersion(), token(revalidated.plan()).familyVersion()),
					() -> assertEquals(token.planVersion(), token(revalidated.plan()).planVersion()),
					() -> assertEquals(1L, harness.variant().runtimePosterior().completeObservations(),
							"a token issued before the re-stamp is still accepted"),
					() -> assertEquals((double) drifted.revision().planningRevisions().learnedEvidenceRevision(),
							revalidated.plan().getDoubleMetricPlanned("optimizer.planCacheEvidenceEpoch"), 0.0d,
							"the served template reports the request's revision"),
					() -> assertEquals(LmdbPipelinePlanCache.evidence(drifted.revision().planningRevisions()),
							harness.variant().evidenceSnapshot()),
					() -> assertEquals("confident-within-stability-envelope",
							exact.plan().getStringMetricPlanned("optimizer.planCacheRefreshReason")),
					() -> assertEquals(1, validator.calls.get(), "the second lookup needs no replay"));
		}
	}

