	@Test
	void aRefreshInFlightAcrossARestampFailsAsStaleAndTheCacheStaysConsistent() throws Exception {
		try (Harness harness = new Harness()) {
			CountDownLatch started = new CountDownLatch(1);
			CountDownLatch release = new CountDownLatch(1);
			LmdbPipelinePlanCache.Context built = learned(17L, 3L);
			harness.refreshWork = harness.blockingRefreshWork(learned(17L, 30L), started, release);
			harness.publish(built, true);
			// A changed read takes today's path: a stale serve that submits the detached refresh.
			LmdbPipelinePlanCache.Result stale = harness.lookup(learned(17L, 30L), true,
					new StubValidator(LmdbPlanningReadLog.Verdict.CHANGED, LmdbPlanningReadLog.LOGICAL));
			assertEquals("USE_AND_REFRESH", stale.plan().getStringMetricPlanned("optimizer.planCacheLookupOutcome"));
			assertTrue(started.await(30, TimeUnit.SECONDS), "COVERAGE_PREREQUISITE: the refresh runs");
			// Inside the refresh's publication window a request revalidates and re-stamps the variant.
			LmdbPipelinePlanCache.Context revalidatedAt = learned(17L, 31L);
			AtomicReference<LmdbPipelinePlanCache.Result> revalidated = new AtomicReference<>();
			Runnable previous = harness.decisions()
					.setBeforeRefreshCommitForTest(() -> revalidated.set(harness
							.lookup(revalidatedAt, true, new StubValidator(LmdbPlanningReadLog.Verdict.IDENTICAL))));
			try {
				release.countDown();
				harness.awaitRefreshTasks();
			} finally {
				harness.decisions().setBeforeRefreshCommitForTest(previous);
			}

			assertAll(
					() -> assertNotNull(revalidated.get()),
					() -> assertEquals(LmdbPlanCacheRevalidation.REVALIDATED,
							revalidated.get().plan().getStringMetricPlanned("optimizer.planCacheRefreshReason")),
					() -> assertEquals(1L, harness.revalidation().refreshLostToRestamp()),
					() -> assertEquals(LmdbPipelinePlanCache.evidence(revalidatedAt.revision().planningRevisions()),
							harness.variant().evidenceSnapshot(), "the re-stamped variant stays"),
					() -> assertEquals(recomputedCharges(harness.decisions()), harness.cache.retainedBytes(),
							"the charged bytes equal a recomputation"));
		}
	}

